TOOLS:
foreign_language|use=Tra bảng quy đổi chứng chỉ/điểm ngoại ngữ sang bậc tương đương, gồm kỹ năng, kể cả khi chưa biết điểm/bậc; không tự xác lập chuẩn đầu ra bắt buộc. Hỏi chuẩn tốt nghiệp theo chứng chỉ cần bảng này cùng quy định qua RAG.|intents=direct_value,list_items|required={"direct_value":[],"list_items":[]}|slots={"certificate_or_language":{"type":"string"},"score_or_level":{"type":["string","number"]},"listening_score":{"type":["string","number"]},"reading_score":{"type":["string","number"]},"speaking_score":{"type":["string","number"]},"writing_score":{"type":["string","number"]}}
study_duration|use=Tra thời gian học chuẩn/tối đa theo hệ đào tạo và loại chương trình trong sổ tay của khóa; chưa rõ phạm vi thì giữ các trường hợp. Không tính thời gian còn lại từ tín chỉ miễn; điều kiện gia hạn/bảo lưu dùng RAG.|intents=direct_value,list_items|required={"direct_value":[],"list_items":[]}|slots={"training_mode":{"type":"string","values":{"chinh_quy":"chính quy","vua_lam_vua_hoc":"vừa làm vừa học"}},"program_type":{"type":"string","values":{"first_degree":"cấp bằng thứ nhất","college_bridge":"liên thông từ cao đẳng","secondary_bridge":"liên thông từ trung cấp","second_degree":"bằng đại học thứ hai"}}}
scholarship_classification|use=Tra mức tiền, công thức tiền, hệ số, căn cứ học phí hoặc xếp loại HBKKHT của từng loại kèm khoảng điểm học bổng, điểm học tập và rèn luyện, hoặc xếp loại học tập và rèn luyện tương ứng. Mức tiền phụ thuộc tín chỉ/học phí, không phải số tiền cố định. Tổng quan không điền aspect để lấy cả bảng điều kiện xét và thang điểm tham chiếu; quyền hưởng, ngoại lệ và kết luận được cấp học bổng cần quy định RAG.|intents=direct_value,list_items|required={"direct_value":[],"list_items":[]}|slots={"aspect":{"type":"string","values":{"amount":"mức tiền","classification":"xếp loại"}},"score_or_label":{"type":["string","number"]}}
scoring|use=Tra bảng quy đổi điểm học phần, xếp loại học lực hoặc phân loại tổng điểm rèn luyện; quy tắc chấm từng tiêu chí thành phần và chính sách học bổng dùng RAG.|intents=direct_value,list_items|required={"direct_value":[],"list_items":[]}|slots={"operation":{"type":"string","values":{"grade_10_to_letter":"quy đổi điểm chữ","pass_fail_ungraded":"học phần đạt không phân mức","letter_to_grade_4":"quy đổi sang thang 4","academic_classification":"xếp loại học lực","conduct_classification":"xếp loại rèn luyện","pass_threshold":"qua môn"}},"score_or_grade":{"type":["string","number"]},"course_scope":{"type":"string","values":{"foundation":"học phần nền tảng","remaining":"học phần còn lại","graded":"môn tính GPA","pass_fail_ungraded":"học phần đạt không phân mức"}}}
student_service|use=Tra đơn vị thực hiện một việc trong danh bạ dịch vụ và liên hệ của đơn vị đó, không cần biết tên đơn vị. Yêu cầu xem xét lại một kết quả hay quyết định đã có (khiếu nại, phúc khảo), các bước, điều kiện, thời hạn hoặc người giải quyết theo quy chế dùng RAG.|intents=direct_value,contact|required={"direct_value":["requested_field"],"contact":["requested_field"]}|slots={"service":{"type":"string"},"requested_field":{"type":"string","values":{"unit":"đơn vị","phone":"phone","email":"email","office":"địa chỉ","website":"website","all":"thông tin liên hệ"}}}
office|use=Tra liên hệ, địa chỉ hoặc dịch vụ của đơn vị đã nêu tên trong danh bạ phòng ban/đơn vị dịch vụ. Đơn vị học thuật trong danh bạ khoa dùng faculty; chỉ biết việc cần hỗ trợ dùng student_service. Trách nhiệm pháp quy, các bước thủ tục hoặc biểu mẫu dùng RAG.|intents=contact|required={"contact":["office","requested_field"]}|slots={"office":{"type":"string"},"requested_field":{"type":"string","values":{"phone":"phone","email":"email","office":"địa chỉ","website":"website","services":"dịch vụ","all":"thông tin liên hệ"}}}
faculty|use=Tra email, số điện thoại kèm số nội bộ, website hoặc địa chỉ của đơn vị học thuật có hồ sơ trong danh bạ khoa, gồm Khoa/Tổ; không dùng cho danh sách ngành hoặc trách nhiệm pháp quy.|intents=contact|required={"contact":["faculty","requested_field"]}|slots={"faculty":{"type":"string"},"requested_field":{"type":"string","values":{"phone":"phone","email":"email","office":"địa chỉ","website":"website","all":"thông tin liên hệ"}}}
program|use=Tra danh sách/sự có mặt của ngành, khoa phụ trách, liên hệ khoa và cơ hội nghề nghiệp ghi trong sổ tay của khóa; ngành kèm email khoa là một task. Không xác nhận tuyển sinh hiện tại, điểm chuẩn hoặc thị trường việc làm ngoài sổ tay.|intents=direct_value,list_items,exists|required={"direct_value":["program_or_faculty","requested_field"],"list_items":["scope"],"exists":["program_or_faculty"]}|slots={"program_or_faculty":{"type":"string"},"requested_field":{"type":"string","values":["faculty","programs","exists","career","email","phone","website","office","all"]},"scope":{"type":"string","values":{"school":"các ngành của trường","faculty":"khoa"}}}
formula|use=Tra công thức và định nghĩa biến/thang điểm/làm tròn có trong nguồn: điểm học bổng từ điểm học tập và rèn luyện=scholarship_score; GPA có trọng số=gpa_weighted_average. Mức tiền, xếp loại hoặc khoảng điểm học bổng dùng scholarship_classification; điều kiện áp dụng, quyền hưởng và ngoại lệ dùng RAG. Không phải calculator số học tổng quát.|intents=formula|required={"formula":["formula_type"]}|slots={"formula_type":{"type":"string","values":["scholarship_score","gpa_weighted_average"]}}

